document.addEventListener("DOMContentLoaded",()=>{initClass10NotesScrollAnimations()});function initClass10NotesScrollAnimations(){const e=new IntersectionObserver(t=>{t.forEach(o=>{o.isIntersecting&&(o.target.classList.add("active"),e.unobserve(o.target))})},{threshold:.08});document.querySelectorAll(".sj-card, .calc-box, .box-ncert, .box-formula, .box-pyq, .box-mistake, .box-tip, .accordion-item, .quiz-container").forEach(t=>{t.classList.add("reveal"),e.observe(t)})}function toggleAccordion(e){const c=e.nextElementSibling,t=e.querySelector(".fa-chevron-down, .fa-chevron-up");c&&c.classList.contains("accordion-body")&&(c.classList.contains("open")?(c.classList.remove("open"),t&&t.classList.replace("fa-chevron-up","fa-chevron-down"),e.classList.remove("active")):(c.classList.add("open"),t&&t.classList.replace("fa-chevron-down","fa-chevron-up"),e.classList.add("active")))}function checkQuiz(e,c){const o=e.parentElement.querySelectorAll(".quiz-option");o.forEach(s=>{s.style.pointerEvents="none"}),c?(e.classList.add("correct","pop"),e.innerHTML+=' <i class="fas fa-check-circle"></i>'):(e.classList.add("wrong","shake"),e.innerHTML+=' <i class="fas fa-times-circle"></i>',setTimeout(()=>{const s=Array.from(o).find(n=>n.getAttribute("onclick")?.includes("true"));s&&!s.classList.contains("correct")&&(s.classList.add("correct","pop"),s.innerHTML+=' <i class="fas fa-check-circle"></i>')},500))}let ticking=!1;window.addEventListener("scroll",()=>{ticking||(window.requestAnimationFrame(()=>{const e=document.getElementById("myBar");if(e){const c=document.documentElement.scrollTop||document.body.scrollTop,t=document.documentElement.scrollHeight-document.documentElement.clientHeight;e.style.width=t>0?c/t*100+"%":"0%"}ticking=!1}),ticking=!0)},{passive:!0});
